import hashlib


def q584(candidates, verify):
    cache = {}
    results = []
    for source in candidates:
        key = hashlib.sha256(source.encode("utf-8")).hexdigest()
        if key not in cache:
            cache[key] = verify(source)
        results.append(
            {"source": source, "hash": key, "result": cache[key]}
        )
    return results
